def generate_edge_ngram(keyword, min_size=3):
    tokens = []
    previous_char = ""

    for letter in keyword:
        previous_char += letter
        if len(previous_char) >= min_size:
            tokens.append(previous_char)

    return tokens


def generate_ngram(keyword, size=3):
    tokens = []

    if len(keyword) >= size:
        for i in range(0, len(keyword) - size + 1):
            tokens.append(keyword[i:i + size])

    return tokens


def splitSKU(meta, enable_edge_ngram=True, enable_ngram=True, min_size=3):
    keywords = meta.split()
    searchable_keywords = []

    for keyword in keywords:
        keyword = keyword.strip()

        if len(keyword) == 0:
            continue

        if enable_ngram:
            searchable_keywords += generate_ngram(keyword, min_size)

        if enable_edge_ngram:
            searchable_keywords += generate_edge_ngram(keyword, min_size)

    # remove duplicates while preserving order
    unique_keywords = []
    for token in searchable_keywords:
        if token not in unique_keywords:
            unique_keywords.append(token)

    return ';'.join(unique_keywords)


def splitSpace(prod):
    parts = prod.split(' ')
    newparts = ''

    for nr in range(1, len(parts)):
        newparts += prod.replace(' ', '', nr) + ';'

    return newparts


