import re
import json

JSONLD_RE = re.compile(r'<script[^>]*ld\+json[^>]*>(.*?)</script\s*>',
                       re.IGNORECASE | re.DOTALL)
RATING_RE = re.compile(r'([\d]+(?:[.,][\d]+)?)\s*out\s*(?:of\s*)?5\s*stars?.*?([\d,]+)\s*reviews?',
                       re.IGNORECASE | re.DOTALL)
NUM_RE = re.compile(r'[\d][\d\s.,\xa0]*\d|\d')

CURRENCY = {'GBP': '£', 'EUR': '€', 'USD': '$', 'CHF': 'CHF',
            'DKK': 'kr', 'NOK': 'kr', 'SEK': 'kr', 'PLN': 'zł', 'CZK': 'Kč'}
SUFFIX_CURRENCIES = ('DKK', 'NOK', 'SEK', 'PLN', 'CZK')

OBJECTTYPE_RULES = [
    (r'/p/[A-Za-z]?-?\d+$',                                         'Shop'),
    (r'/choosing-|/find-the-right-|/blog/|/airmini-cpap-device$',    'Blogs'),
    (r'/c/\d+$',                                                    'Collections'),
    (r'/customer/|/about/|/terms|/privacy|/cookies|/vatinfo'
     r'|/sitemap|/airview/|/[a-z]{2}/[a-z]{2}$',                    'Pages'),
]


def meta(key):
    val = document.get_meta_data_value(key)
    return val[0] if val else ''


def to_float(raw):
    """Handles 949, 949.00, 949,00, 1.234,56 and 1,234.56."""
    if raw is None:
        return None
    text = str(raw).strip().replace(' ', '').replace('\xa0', '')
    if ',' in text and '.' in text:
        text = text.replace('.', '').replace(',', '.') if text.rfind(',') > text.rfind('.') \
            else text.replace(',', '')
    elif ',' in text:
        text = text.replace(',', '.') if len(text.split(',')[-1]) == 2 else text.replace(',', '')
    try:
        return float(text)
    except ValueError:
        return None


def format_price(amount, code):
    symbol = CURRENCY.get(code, code)
    body = '{:.2f}'.format(amount)
    return (body + ' ' + symbol) if code in SUFFIX_CURRENCIES else (symbol + body)


def flatten(node):
    if isinstance(node, list):
        for item in node:
            for found in flatten(item):
                yield found
    elif isinstance(node, dict):
        yield node
        for found in flatten(node.get('@graph', [])):
            yield found


def has_type(node, wanted):
    types = node.get('@type', [])
    if isinstance(types, str):
        types = [types]
    return any(isinstance(t, str) and t.split('/')[-1] == wanted for t in types)


def extract_image(img):
    if isinstance(img, str):
        return img
    if isinstance(img, dict):
        return img.get('url') or img.get('contentUrl') or ''
    if isinstance(img, list):
        for item in img:
            found = extract_image(item)
            if found:
                return found
    return ''


def extract_offer(node):
    offers = node.get('offers')
    if isinstance(offers, dict):
        offers = [offers]
    if not isinstance(offers, list):
        return None, '', ''
    for offer in offers:
        if isinstance(offer, dict):
            price = offer.get('price') or offer.get('lowPrice')
            if price is not None:
                availability = str(offer.get('availability', '')).split('/')[-1]
                return price, offer.get('priceCurrency', ''), availability
    return None, '', ''


# ===================== main =====================

uri = ''
for key in ['uri', 'documenturi', 'sysclickableuri', 'clickableuri', 'originaluri']:
    uri = meta(key)
    if uri:
        break

if not uri:
    log('WARNING: Could not detect URI', 'Warning')
else:
    path = re.sub(r'[?#].*$', '', uri).rstrip('/')

    objecttype = 'Others'
    for pattern, value in OBJECTTYPE_RULES:
        if re.search(pattern, path, flags=re.IGNORECASE):
            objecttype = value
            break
    document.add_meta_data({'objecttype': objecttype})

    if objecttype == 'Shop':
        price = None
        currency = ''

        # ---------- schema.org ----------
        for block in JSONLD_RE.findall(meta('schemaorg')):
            try:
                parsed = json.loads(block.strip())
            except ValueError:
                continue

            product = next((n for n in flatten(parsed) if has_type(n, 'Product')), None)
            if not product:
                continue

            name = (product.get('name') or '').strip()
            if name:
                document.add_meta_data({'productname': name, 'ogimagealt': name})

            image = extract_image(product.get('image'))
            if image:
                document.add_meta_data({'thumbnailurl': image})

            brand = product.get('brand')
            if isinstance(brand, dict):
                brand = brand.get('name')
            document.add_meta_data({'productbrand': (brand or '').strip() or 'ResMed'})

            sku = (product.get('sku') or '').strip()
            if sku:
                document.add_meta_data({'productsku': sku})

            raw_price, currency, availability = extract_offer(product)
            price = to_float(raw_price)
            if availability:
                document.add_meta_data({'productavailability': availability})
            break

        # ---------- breadcrumb categories ----------
        crumbs = []
        for block in JSONLD_RE.findall(meta('schemaorg')):
            try:
                parsed = json.loads(block.strip())
            except ValueError:
                continue
            for node in flatten(parsed):
                if not has_type(node, 'BreadcrumbList'):
                    continue
                items = sorted(node.get('itemListElement', []),
                               key=lambda i: i.get('position', 0))
                for item in items[1:-1]:
                    label = (item.get('name') or '').split('|')[0].strip()
                    if label:
                        crumbs.append(label)
        if crumbs:
            document.add_meta_data({'productcategory': crumbs,
                                    'categorypath': '|'.join(crumbs)})

        # ---------- scraped: list price + badge ----------
        list_price = None
        raw_list = meta('domlistprice')
        if raw_list:
            found = NUM_RE.search(raw_list)
            if found:
                list_price = to_float(found.group(0))

        badge = meta('dombadge').strip()
        if badge:
            document.add_meta_data({'productbadge': badge})

        # ---------- scraped: Yotpo rating ----------
        bottom_line = document.get_meta_data_value('yotpobottomline')
        if bottom_line:
            if len(bottom_line) > 1:
                log('Multiple Yotpo widgets on ' + uri, 'Warning')
            found = RATING_RE.search(bottom_line[0])
            if found:
                document.add_meta_data({
                    'productrating': to_float(found.group(1)),
                    'reviewcount': int(found.group(2).replace(',', ''))
                })
            else:
                log('Yotpo label unparsed: ' + bottom_line[0][:120], 'Warning')

        # ---------- price block ----------
        if price is not None:
            currency = currency or 'GBP'
            document.add_meta_data({
                'productprice': price,
                'pricecurrency': currency,
                'product_price': format_price(price, currency)
            })
            if list_price and list_price > price:
                document.add_meta_data({
                    'productlistprice': list_price,
                    'productdiscountpercent': int(round((list_price - price) / list_price * 100))
                })
        else:
            log('No price found for ' + uri, 'Warning')

